const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const trigger = $input.all()[i].json;

  const workflowName = (trigger.workflow && trigger.workflow.name) || 'Unknown Workflow';
  const workflowId = (trigger.workflow && trigger.workflow.id) || null;

  // Execution metadata: comes from trigger.execution for node errors
  const executionId = trigger.execution && trigger.execution.id ? String(trigger.execution.id) : null;
  const executionUrl = trigger.execution && trigger.execution.url ? trigger.execution.url : null;

  // Error metadata: try nested shape first, fall back to flat shape
  let errorNode = null;
  let errorMessage = null;
  let errorClass = null;
  let errorTimestamp = null;

  // Nested shape (HTTP node errors)
  if (trigger.execution && trigger.execution.error) {
    const err = trigger.execution.error;
    if (err.node && err.node.name) errorNode = err.node.name;
    if (err.description) errorMessage = err.description;
    if (err.name) errorClass = err.name;
    if (err.timestamp) errorTimestamp = err.timestamp;
  }

  // Flat shape (expression errors) â€” only used if nested did not populate
  if (!errorNode && trigger.lastNodeExecuted) errorNode = trigger.lastNodeExecuted;
  if (!errorMessage && trigger.message) errorMessage = trigger.message;
  if (!errorClass && trigger.name) errorClass = trigger.name;
  if (!errorTimestamp && trigger.executionContext && trigger.executionContext.establishedAt) {
    errorTimestamp = trigger.executionContext.establishedAt;
  }

  // Final fallbacks
  errorNode = errorNode || 'Unknown Node';
  errorMessage = errorMessage || 'No error message';
  errorClass = errorClass || 'UnknownError';
  errorTimestamp = errorTimestamp || Date.now();

  const triggerTime = new Date(errorTimestamp).toISOString();

  // Unique key. Uses execution ID if available, timestamp otherwise.
  const webhookId = executionId
    ? 'error-exec-' + executionId
    : 'error-' + errorTimestamp;

  results.push({
    json: {
      webhook_id: webhookId,
      workflow_name: workflowName,
      workflow_id: workflowId,
      execution_id: executionId,
      execution_url: executionUrl,
      error_node: errorNode,
      error_message: errorMessage,
      error_class: errorClass,
      error_timestamp: triggerTime
    }
  });
}

return results;

// Build the INSERT statement for the error row.
// Uses ON CONFLICT DO UPDATE so a failure row always lands, even if a prior row exists.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const d = $input.all()[i].json;

  const esc = (v) => {
    if (v === null || v === undefined) return 'NULL';
    return "'" + String(v).replace(/'/g, "''") + "'";
  };

  // Build the error message. Include class, node, message, and execution URL when available.
  const errorParts = [];
  if (d.error_class) errorParts.push(d.error_class);
  if (d.error_node) errorParts.push(d.error_node);
  if (d.error_message) errorParts.push(d.error_message);
  let errorMessage = errorParts.join(': ');
  if (d.execution_url) errorMessage += ' | ' + d.execution_url;

  const sql = `INSERT INTO shopify_webhook_runs (
    webhook_id,
    topic,
    order_id,
    customer_email,
    shopify_note_status,
    processed_at,
    error_message
  ) VALUES (
    ${esc(d.webhook_id)},
    'workflow_error',
    ${esc(d.order_id)},
    ${esc(d.customer_email)},
    'failed',
    NOW(),
    ${esc(errorMessage)}
  )
  ON CONFLICT (webhook_id) DO UPDATE SET
    error_message = EXCLUDED.error_message,
    shopify_note_status = 'failed',
    processed_at = NOW();`;

  results.push({
    json: Object.assign({}, d, {
      sql_query: sql
    })
  });
}

return results;
